    M(["Perché i vini migliori di Nero di Troia costano di più da produrre?", "Pourquoi les meilleurs vins de Nero di Troia coûtent-ils plus cher à produire ?", "Why are top Nero di Troia wines costly to produce?", "¿Por qué los mejores vinos de Nero di Troia cuestan más de producir?"],
      [["Gli acini maturano in tempi diversi: servono più passaggi o una cernita", "Les baies mûrissent à des moments différents : il faut plusieurs passages ou un tri", "Berries ripen at different times: several passes or sorting are needed", "Las bayas maduran en momentos distintos: hacen falta varias pasadas o selección"],
       ["Si deve irrigare a goccia", "Il faut irriguer au goutte-à-goutte", "Drip irrigation is compulsory", "Hay que regar por goteo"],
       ["Matura in luglio con il caldo", "Il mûrit en juillet en pleine chaleur", "It ripens in July in the heat", "Madura en julio con el calor"],
       ["Ha la buccia sottile e marcisce sempre", "Il a la peau fine et pourrit toujours", "It is thin-skinned and always rots", "Tiene la piel fina y siempre se pudre"]],
      ["Matura tardi, teme le piogge d'autunno e la peronospora; tannini alti ma fini.", "Il mûrit tard, craint les pluies d'automne et le mildiou ; tanins élevés mais fins.", "It ripens late and fears autumn rain and downy mildew; high but fine tannins.", "Madura tarde, teme las lluvias de otoño y el mildiu; taninos altos pero finos."])
